function build(raw: Omit<Place, 'slug' | 'stateSlug' | 'verified'>[], verified: boolean): Place[] {
  return raw.map((p) => ({
    ...p,
    slug: slugify(p.name),
    stateSlug: slugify(p.state),
    verified
  }));
}

export const PLACES: Place[] = [
  ...build([...rawKarnataka, ...holidifyKarnatakaSupplemental, ...trawellKarnatakaSupplemental], true),
  ...build([...rawOtherStates, ...trawellTelanganaSupplemental, ...trawellMaharashtraSupplemental, ...trawellTamilNaduSupplemental, ...thrillophiliaAndhraPradeshSupplemental, ...holidifyArunachalPradeshSupplemental, ...holidifyArunachalPradeshExtendedSupplemental, ...delhiTourismSupplemental, ...trawellKeralaSupplemental, ...trawellMadhyaPradeshSupplemental, ...trawellWestBengalSupplemental, ...holidifyWestBengalSupplemental, ...holidifyGoaSupplemental, ...holidifyGoaExtendedSupplemental, ...thrillophiliaPunjabSupplemental, ...trawellRajasthanSupplemental, ...thrillophiliaBiharSupplemental, ...holidifyBiharSupplemental, ...holidifyOdishaSupplemental, ...holidifyMeghalayaSupplemental, ...travelsetuNagalandSupplemental, ...holidifyAssamSupplemental, ...trawellGujaratSupplemental, ...thrillophiliaSikkimSupplemental], true)
];

export function getStates() {
  const map = new Map<string, { name: string; slug: string; count: number }>();
  for (const p of PLACES) {
    const existing = map.get(p.stateSlug);
    if (existing) existing.count++;
    else map.set(p.stateSlug, { name: p.state, slug: p.stateSlug, count: 1 });
  }
  return [...map.values()].sort((a, b) => a.name.localeCompare(b.name));
}

export function getPlaceBySlug(slug: string) {
  return PLACES.find((p) => p.slug === slug) ?? null;
}

export function getPlacesByState(stateSlug: string) {
  return PLACES.filter((p) => p.stateSlug === stateSlug);
}
